<?php require_once __DIR__.'/../includes/bootstrap.php';$q=trim($_GET['q']??'');$sql="SELECT c,u.name AS producer FROM casting_calls c JOIN users u ON u.id=c.user_id WHERE c.status='open'";$args=[];if($q!==''){$sql.=' AND (c.title LIKE ? OR c.city LIKE ? OR c.project_type LIKE ?)';$args=["%$q%","%$q%","%$q%"];} $sql.=' ORDER BY c.created_at DESC';$s=db()->prepare($sql);$s->execute($args);$jobs=$s->fetchAll();$me=current_user();$pageTitle='Casting calls · CineCast';require __DIR__.'/../includes/header.php';?><main class="page-wrap"><div class="container"><div class="eyebrow dark">FIND YOUR NEXT ROLE</div><h1 class="page-title">Casting <em style="color:var(--orange)">calls.</em></h1><form class="search-row"><input class="search-input" name="q" value="<?=e($q)?>" placeholder="Search project, city or type"><button class="btn btn-dark">Search</button></form><?php if(!$jobs):?><div class="empty-state">No open casting calls found. Try another search, or check back soon.</div><?php else:?><div class="cards-list"><?php foreach($jobs as $j):?><article class="job-card"><div class="job-meta"><span><?=e($j['project_type'])?></span><span><?=e($j['city'])?></span></div><h3><?=e($j['title'])?></h3><p><?=e(mb_strimwidth($j['description'],0,180,'…'))?></p><p><strong>Role:</strong> <?=e($j['role_description'])?></p><p><strong>Age:</strong> <?=e($j['age_min']??'Any')?>–<?=e($j['age_max']??'Any')?> · <strong>Gender:</strong> <?=e($j['gender'])?></p><div class="job-actions"><a class="btn btn-dark" href="<?=e(url('casting/view.php?id='.$j['id']))?>">View details ↗</a><?php if($j['deadline']):?><span class="muted">Deadline <?=e(date('d M Y',strtotime($j['deadline'])))?></span><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></div></main><?php require __DIR__.'/../includes/footer.php'; ?>